"""No watermarks or branding strings in shipped code and docs.

Scans the files that ship to the repository (src, scripts, README,
docs, packaging, CI) for a small explicit blocklist. The test suite
itself is excluded, because this file contains the blocklist. Results
JSON is excluded: it carries method names and measured numbers only.
"""

from pathlib import Path

BLOCKLIST = [
    "Muse",
    "Claude",
    "Anthropic",
    "AI-generated",
    "generated by",
    "watermark",
    "as an AI",
]

ROOT = Path(__file__).resolve().parents[1]
SCAN_DIRS = ["src", "scripts", "docs", ".github"]
SCAN_FILES = ["README.md", "pyproject.toml", "requirements.txt", "LICENSE"]


def _scanned_files():
    for d in SCAN_DIRS:
        for path in (ROOT / d).rglob("*"):
            if path.is_file() and path.suffix in (".py", ".md", ".toml",
                                                  ".yml", ".txt"):
                yield path
    for name in SCAN_FILES:
        path = ROOT / name
        if path.exists():
            yield path


def test_no_branding_strings():
    hits = []
    for path in _scanned_files():
        text = path.read_text(errors="ignore")
        for bad in BLOCKLIST:
            if bad in text:
                hits.append(f"{path.relative_to(ROOT)}: {bad!r}")
    assert not hits, "; ".join(hits)
